def get_combined_config(name, val, default=None):
    """Consolidate the config with priority from high to low provided init
    value > OS environ > default."""

    if val is not None:
        return val

    env = load_dash_env_vars().get(f"DASH_{name.upper()}")
    if env is None:
        return default

    return env.lower() == "true" if env.lower() in {"true", "false"} else env

def _setup_dev_tools(self, **kwargs):
    debug = kwargs.get("debug", False)
    dev_tools = self._dev_tools = AttributeDict()

    for attr in (
        "ui",
        "props_check",
        "serve_dev_bundles",
        "hot_reload",
        "silence_routes_logging",
        "prune_errors",
    ):
        dev_tools[attr] = get_combined_config(
            attr, kwargs.get(attr, None), default=debug
        )

    for attr, _type, default in (
        ("hot_reload_interval", float, 3),
        ("hot_reload_watch_interval", float, 0.5),
        ("hot_reload_max_retry", int, 8),
    ):
        dev_tools[attr] = _type(
            get_combined_config(attr, kwargs.get(attr, None), default=default)
        )

    return dev_tools

