def create_callback_id(output, inputs):
    # A single dot within a dict id key or value is OK
    # but in case of multiple dots together escape each dot
    # with `\` so we don't mistake it for multi-outputs
    hashed_inputs = None

    def _concat(x):
        nonlocal hashed_inputs
        _id = x.component_id_str().replace(".", "\\.") + "." + x.component_property
        if x.allow_duplicate:
            if not hashed_inputs:
                hashed_inputs = hashlib.md5(
                    ".".join(str(x) for x in inputs).encode("utf-8")
                ).hexdigest()
            # Actually adds on the property part.
            _id += f"@{hashed_inputs}"
        return _id

    if isinstance(output, (list, tuple)):
        return ".." + "...".join(_concat(x) for x in output) + ".."

    return _concat(output)

def _concat(x):
    nonlocal hashed_inputs
    _id = x.component_id_str().replace(".", "\\.") + "." + x.component_property
    if x.allow_duplicate:
        if not hashed_inputs:
            hashed_inputs = hashlib.md5(
                ".".join(str(x) for x in inputs).encode("utf-8")
            ).hexdigest()
        # Actually adds on the property part.
        _id += f"@{hashed_inputs}"
    return _id

def validate_long_inputs(deps):
    for dep in deps:
        if dep.has_wildcard():
            raise WildcardInLongCallback(
                f"""
                long callbacks does not support dependencies with
                pattern-matching ids
                    Received: {repr(dep)}\n"""
            )

def has_wildcard(self):
    """
    Return true if id contains a wildcard (MATCH, ALL, or ALLSMALLER)
    """
    if isinstance(self.component_id, dict):
        for v in self.component_id.values():
            if isinstance(v, _Wildcard):
                return True
    return False

