def pytest_addhooks(pluginmanager):
    if not _installed:
        return
    # https://github.com/pytest-dev/pytest-xdist/blob/974bd566c599dc6a9ea291838c6f226197208b46/xdist/plugin.py#L67
    # avoid warnings with pytest-2.8
    from dash.testing import newhooks  # pylint: disable=import-outside-toplevel

    method = getattr(pluginmanager, "add_hookspecs", None)
    if method is None:
        method = pluginmanager.addhooks  # pragma: no cover
    method(newhooks)

def extract_grouped_output_callback_args(args, kwargs):
    if "output" in kwargs:
        parameters = kwargs["output"]
        # Normalize list/tuple of multiple positional outputs to a tuple
        if isinstance(parameters, (list, tuple)):
            parameters = list(parameters)

        # Make sure dependency grouping contains only Output objects
        for dep in flatten_grouping(parameters):
            if not isinstance(dep, Output):
                raise ValueError(
                    f"Invalid value provided where an Output dependency "
                    f"object was expected: {dep}"
                )

        return parameters

    parameters = []
    while args:
        next_deps = flatten_grouping(args[0])
        if all(isinstance(d, Output) for d in next_deps):
            parameters.append(args.pop(0))
        else:
            break
    return parameters

def flatten_grouping(grouping, schema=None):
    """
    Convert a grouping value to a list of scalar values

    :param grouping: grouping value to flatten
    :param schema: If provided, a grouping value representing the expected structure of
        the input grouping value. If not provided, the grouping value is its own schema.
        A schema is required in order to be able treat tuples and dicts in the input
        grouping as scalar values.

    :return: list of the scalar values in the input grouping
    """
    if schema is None:
        schema = grouping
    else:
        validate_grouping(grouping, schema)

    if isinstance(schema, (tuple, list)):
        return [
            g
            for group_el, schema_el in zip(grouping, schema)
            for g in flatten_grouping(group_el, schema_el)
        ]

    if isinstance(schema, dict):
        return [g for k in schema for g in flatten_grouping(grouping[k], schema[k])]

    return [grouping]

def make_grouping_by_index(schema, flat_values):
    """
    Make a grouping like the provided grouping schema, with scalar values drawn from a
    flat list by index.

    Note: Scalar values in schema are not used

    :param schema: Grouping value encoding the structure of the grouping to return
    :param flat_values: List of values with length matching the grouping_len of schema.
        Elements of flat_values will become the scalar values in the resulting grouping
    """

    def _perform_make_grouping_like(value, next_values):
        if isinstance(value, (tuple, list)):
            return list(
                _perform_make_grouping_like(el, next_values)
                for i, el in enumerate(value)
            )

        if isinstance(value, dict):
            return {
                k: _perform_make_grouping_like(v, next_values)
                for i, (k, v) in enumerate(value.items())
            }

        return next_values.pop(0)

    if not isinstance(flat_values, list):
        raise ValueError(
            "The flat_values argument must be a list. "
            f"Received value of type {type(flat_values)}"
        )

    expected_length = len(flatten_grouping(schema))
    if len(flat_values) != expected_length:
        raise ValueError(
            f"The specified grouping pattern requires {expected_length} "
            f"elements but received {len(flat_values)}\n"
            f"    Grouping pattern: {repr(schema)}\n"
            f"    Values: {flat_values}"
        )

    return _perform_make_grouping_like(schema, list(flat_values))

def _perform_make_grouping_like(value, next_values):
    if isinstance(value, (tuple, list)):
        return list(
            _perform_make_grouping_like(el, next_values)
            for i, el in enumerate(value)
        )

    if isinstance(value, dict):
        return {
            k: _perform_make_grouping_like(v, next_values)
            for i, (k, v) in enumerate(value.items())
        }

    return next_values.pop(0)

def wrap_func(func):

    if long is not None:
        long_key = BaseLongCallbackManager.register_func(
            func,
            long.get("progress") is not None,
            callback_id,
        )

    @wraps(func)
    def add_context(*args, **kwargs):
        output_spec = kwargs.pop("outputs_list")
        app_callback_manager = kwargs.pop("long_callback_manager", None)
        callback_ctx = kwargs.pop("callback_context", {})
        callback_manager = long and long.get("manager", app_callback_manager)
        _validate.validate_output_spec(insert_output, output_spec, Output)

        context_value.set(callback_ctx)

        func_args, func_kwargs = _validate.validate_and_group_input_args(
            args, inputs_state_indices
        )

        response = {"multi": True}

        if long is not None:
            if not callback_manager:
                raise MissingLongCallbackManagerError(
                    "Running `long` callbacks requires a manager to be installed.\n"
                    "Available managers:\n"
                    "- Diskcache (`pip install dash[diskcache]`) to run callbacks in a separate Process"
                    " and store results on the local filesystem.\n"
                    "- Celery (`pip install dash[celery]`) to run callbacks in a celery worker"
                    " and store results on redis.\n"
                )

            progress_outputs = long.get("progress")
            cache_key = flask.request.args.get("cacheKey")
            job_id = flask.request.args.get("job")
            old_job = flask.request.args.getlist("oldJob")

            current_key = callback_manager.build_cache_key(
                func,
                # Inputs provided as dict is kwargs.
                func_args if func_args else func_kwargs,
                long.get("cache_args_to_ignore", []),
            )

            if old_job:
                for job in old_job:
                    callback_manager.terminate_job(job)

            if not cache_key:
                cache_key = current_key

                job_fn = callback_manager.func_registry.get(long_key)

                job = callback_manager.call_job_fn(
                    cache_key,
                    job_fn,
                    func_args if func_args else func_kwargs,
                    AttributeDict(
                        args_grouping=callback_ctx.args_grouping,
                        using_args_grouping=callback_ctx.using_args_grouping,
                        outputs_grouping=callback_ctx.outputs_grouping,
                        using_outputs_grouping=callback_ctx.using_outputs_grouping,
                        inputs_list=callback_ctx.inputs_list,
                        states_list=callback_ctx.states_list,
                        outputs_list=callback_ctx.outputs_list,
                        input_values=callback_ctx.input_values,
                        state_values=callback_ctx.state_values,
                        triggered_inputs=callback_ctx.triggered_inputs,
                        ignore_register_page=True,
                    ),
                )

                data = {
                    "cacheKey": cache_key,
                    "job": job,
                }

                running = long.get("running")

                if running:
                    data["running"] = {str(r[0]): r[1] for r in running}
                    data["runningOff"] = {str(r[0]): r[2] for r in running}
                cancel = long.get("cancel")
                if cancel:
                    data["cancel"] = cancel

                progress_default = long.get("progressDefault")
                if progress_default:
                    data["progressDefault"] = {
                        str(o): x
                        for o, x in zip(progress_outputs, progress_default)
                    }
                return to_json(data)
            if progress_outputs:
                # Get the progress before the result as it would be erased after the results.
                progress = callback_manager.get_progress(cache_key)
                if progress:
                    response["progress"] = {
                        str(x): progress[i] for i, x in enumerate(progress_outputs)
                    }

            output_value = callback_manager.get_result(cache_key, job_id)
            # Must get job_running after get_result since get_results terminates it.
            job_running = callback_manager.job_running(job_id)
            if not job_running and output_value is callback_manager.UNDEFINED:
                # Job canceled -> no output to close the loop.
                output_value = NoUpdate()

            elif (
                isinstance(output_value, dict)
                and "long_callback_error" in output_value
            ):
                error = output_value.get("long_callback_error")
                raise LongCallbackError(
                    f"An error occurred inside a long callback: {error['msg']}\n{error['tb']}"
                )

            if job_running and output_value is not callback_manager.UNDEFINED:
                # cached results.
                callback_manager.terminate_job(job_id)

            if multi and isinstance(output_value, (list, tuple)):
                output_value = [
                    NoUpdate() if NoUpdate.is_no_update(r) else r
                    for r in output_value
                ]

            if output_value is callback_manager.UNDEFINED:
                return to_json(response)
        else:
            # don't touch the comment on the next line - used by debugger
            output_value = func(*func_args, **func_kwargs)  # %% callback invoked %%

        if NoUpdate.is_no_update(output_value):
            raise PreventUpdate

        if not multi:
            output_value, output_spec = [output_value], [output_spec]
            flat_output_values = output_value
        else:
            if isinstance(output_value, (list, tuple)):
                # For multi-output, allow top-level collection to be
                # list or tuple
                output_value = list(output_value)

            # Flatten grouping and validate grouping structure
            flat_output_values = flatten_grouping(output_value, output)

        _validate.validate_multi_return(
            output_spec, flat_output_values, callback_id
        )

        component_ids = collections.defaultdict(dict)
        has_update = False
        for val, spec in zip(flat_output_values, output_spec):
            if isinstance(val, NoUpdate):
                continue
            for vali, speci in (
                zip(val, spec) if isinstance(spec, list) else [[val, spec]]
            ):
                if not isinstance(vali, NoUpdate):
                    has_update = True
                    id_str = stringify_id(speci["id"])
                    prop = clean_property_name(speci["property"])
                    component_ids[id_str][prop] = vali

        if not has_update:
            raise PreventUpdate

        response["response"] = component_ids

        try:
            jsonResponse = to_json(response)
        except TypeError:
            _validate.fail_callback_output(output_value, output)

        return jsonResponse

    callback_map[callback_id]["callback"] = add_context

    return func

def register_func(fn, progress, callback_id):
    key = BaseLongCallbackManager.hash_function(fn, callback_id)
    BaseLongCallbackManager.functions.append(
        (
            key,
            fn,
            progress,
        )
    )

    for manager in BaseLongCallbackManager.managers:
        manager.register(key, fn, progress)

    return key

def hash_function(fn, callback_id=""):
    fn_source = inspect.getsource(fn)
    fn_str = fn_source
    return hashlib.sha1(
        callback_id.encode("utf-8") + fn_str.encode("utf-8")
    ).hexdigest()

