def _add_assets_resource(self, url_path, file_path):
    res = {"asset_path": url_path, "filepath": file_path}
    if self.config.assets_external_path:
        res["external_url"] = self.get_asset_url(url_path.lstrip("/"))
    self._assets_files.append(file_path)
    return res

def _walk_assets_directory(self):
    walk_dir = self.config.assets_folder
    slash_splitter = re.compile(r"[\\/]+")
    ignore_str = self.config.assets_ignore
    ignore_filter = re.compile(ignore_str) if ignore_str else None

    for current, _, files in sorted(os.walk(walk_dir)):
        if current == walk_dir:
            base = ""
        else:
            s = current.replace(walk_dir, "").lstrip("\\").lstrip("/")
            splitted = slash_splitter.split(s)
            if len(splitted) > 1:
                base = "/".join(slash_splitter.split(s))
            else:
                base = splitted[0]

        if ignore_filter:
            files_gen = (x for x in files if not ignore_filter.search(x))
        else:
            files_gen = files

        for f in sorted(files_gen):
            path = "/".join([base, f]) if base else f

            full = os.path.join(current, f)

            if f.endswith("js"):
                self.scripts.append_script(self._add_assets_resource(path, full))
            elif f.endswith("css"):
                self.css.append_css(self._add_assets_resource(path, full))
            elif f == "favicon.ico":
                self._favicon = path

def _on_assets_change(self, filename, modified, deleted):
    _reload = self._hot_reload
    with _reload.lock:
        _reload.hard = True
        _reload.hash = generate_hash()

        if self.config.assets_folder in filename:
            asset_path = (
                os.path.relpath(
                    filename,
                    os.path.commonprefix([self.config.assets_folder, filename]),
                )
                .replace("\\", "/")
                .lstrip("/")
            )

            _reload.changed_assets.append(
                {
                    "url": self.get_asset_url(asset_path),
                    "modified": int(modified),
                    "is_css": filename.endswith("css"),
                }
            )

            if filename not in self._assets_files and not deleted:
                res = self._add_assets_resource(asset_path, filename)
                if filename.endswith("js"):
                    self.scripts.append_script(res)
                elif filename.endswith("css"):
                    self.css.append_css(res)

            if deleted:
                if filename in self._assets_files:
                    self._assets_files.remove(filename)

                def delete_resource(resources):
                    to_delete = None
                    for r in resources:
                        if r.get("asset_path") == asset_path:
                            to_delete = r
                            break
                    if to_delete:
                        resources.remove(to_delete)

                if filename.endswith("js"):
                    # pylint: disable=protected-access
                    delete_resource(self.scripts._resources._resources)
                elif filename.endswith("css"):
                    # pylint: disable=protected-access
                    delete_resource(self.css._resources._resources)

def _filter_resources(self, all_resources, dev_bundles=False):
    filtered_resources = []
    for s in all_resources:
        filtered_resource = {}
        if "dynamic" in s:
            filtered_resource["dynamic"] = s["dynamic"]
        if "async" in s:
            if "dynamic" in s:
                raise exceptions.ResourceException(
                    f"""
                    Can't have both 'dynamic' and 'async'.
                    {json.dumps(filtered_resource)}
                    """
                )

            # Async assigns a value dynamically to 'dynamic'
            # based on the value of 'async' and config.eager_loading
            #
            # True -> dynamic if the server is not eager, False otherwise
            # 'lazy' -> always dynamic
            # 'eager' -> dynamic if server is not eager
            # (to prevent ever loading it)
            filtered_resource["dynamic"] = (
                not self.config.eager_loading
                if s["async"] is True
                else (s["async"] == "eager" and not self.config.eager_loading)
                or s["async"] == "lazy"
            )
        if "namespace" in s:
            filtered_resource["namespace"] = s["namespace"]
        if "external_url" in s and not self.config.serve_locally:
            filtered_resource["external_url"] = s["external_url"]
        elif "dev_package_path" in s and dev_bundles:
            filtered_resource["relative_package_path"] = s["dev_package_path"]
        elif "relative_package_path" in s:
            filtered_resource["relative_package_path"] = s["relative_package_path"]
        elif "absolute_path" in s:
            filtered_resource["absolute_path"] = s["absolute_path"]
        elif "asset_path" in s:
            info = os.stat(s["filepath"])
            filtered_resource["asset_path"] = s["asset_path"]
            filtered_resource["ts"] = info.st_mtime
        elif self.config.serve_locally:
            warnings.warn(
                (
                    "You have set your config to `serve_locally=True` but "
                    f"A local version of {s['external_url']} is not available.\n"
                    "If you added this file with "
                    "`app.scripts.append_script` "
                    "or `app.css.append_css`, use `external_scripts` "
                    "or `external_stylesheets` instead.\n"
                    "See https://dash.plotly.com/external-resources"
                )
            )
            continue
        else:
            raise exceptions.ResourceException(
                f"""
                {json.dumps(filtered_resource)} does not have a
                relative_package_path, absolute_path, or an external_url.
                """
            )

        filtered_resources.append(filtered_resource)

    return filtered_resources

def get_all_resources(self, dev_bundles=False):
    lib_resources = ComponentRegistry.get_resources(self.resource_name)
    all_resources = lib_resources + self._resources

    return self._filter_resources(all_resources, dev_bundles)

def get_resources(cls, resource_name):
    resources = []

    for module_name in cls.registry:
        module = sys.modules[module_name]
        resources.extend(getattr(module, resource_name, []))

    return resources

