    )

def _get_traceback(secret, error: Exception):
    try:
        # pylint: disable=import-outside-toplevel
        from werkzeug.debug import tbtools
    except ImportError:
        tbtools = None

    def _get_skip(text, divider=2):
        skip = 0
        for i, line in enumerate(text):
            if "%% callback invoked %%" in line:
                skip = int((i + 1) / divider)
                break
        return skip

    # werkzeug<2.1.0
    if hasattr(tbtools, "get_current_traceback"):
        tb = tbtools.get_current_traceback()
        skip = _get_skip(tb.plaintext.splitlines())
        return tbtools.get_current_traceback(skip=skip).render_full()

    if hasattr(tbtools, "DebugTraceback"):
        tb = tbtools.DebugTraceback(error)  # pylint: disable=no-member
        skip = _get_skip(tb.render_traceback_text().splitlines())

        # pylint: disable=no-member
        return tbtools.DebugTraceback(error, skip=skip).render_debugger_html(
            True, secret, True
        )

    tb = traceback.format_exception(type(error), error, error.__traceback__)
    skip = _get_skip(tb, 1)
    return tb[0] + "".join(tb[skip:])

def _get_skip(text, divider=2):
    skip = 0
    for i, line in enumerate(text):
        if "%% callback invoked %%" in line:
            skip = int((i + 1) / divider)
            break
    return skip

def set_read_only(self, names, msg="Attribute is read-only"):
    """
    Designate named attributes as read-only with the corresponding msg

    Method is additive. Making additional calls to this method will update
    existing messages and add to the current set of _read_only names.
    """
    new_read_only = {name: msg for name in names}
    if getattr(self, "_read_only", False):
        self._read_only.update(new_read_only)
    else:
        object.__setattr__(self, "_read_only", new_read_only)

def finalize(self, msg="Object is final: No new keys may be added."):
    """Prevent any new keys being set."""
    object.__setattr__(self, "_final", msg)

