def array_of():
    inner = js_to_py_type(type_object["value"])
    if inner:
        return "list of " + (
            inner + "s"
            if inner.split(" ")[0] != "dict"
            else inner.replace("dict", "dicts", 1)
        )
    return "list"

def tuple_of():
    elements = [js_to_py_type(element) for element in type_object["elements"]]
    return f"list of {len(elements)} elements: [{', '.join(elements)}]"

def terminate_job(self, job):
    import psutil  # pylint: disable=import-outside-toplevel,import-error

    if job is None:
        return

    job = int(job)

    # Use diskcache transaction so multiple process don't try to kill the
    # process at the same time
    with self.handle.transact():
        if psutil.pid_exists(job):
            process = psutil.Process(job)

            for proc in process.children(recursive=True):
                try:
                    proc.kill()
                except psutil.NoSuchProcess:
                    pass

            try:
                process.kill()
            except psutil.NoSuchProcess:
                pass

            try:
                process.wait(1)
            except (psutil.TimeoutExpired, psutil.NoSuchProcess):
                pass

def terminate_unhealthy_job(self, job):
    import psutil  # pylint: disable=import-outside-toplevel,import-error

    job = int(job)

    if job and psutil.pid_exists(job):
        if not self.job_running(job):
            self.terminate_job(job)
            return True

    return False

